ir.html#Tabati&#232;re&quot; title=&quot;March&#233; noir&quot;&gt;↓&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Tabati&#232;re-(Objet).html&quot; title=&quot;Tabati&#232;re&quot;&gt;Tabati&#232;re (en &#233;tain ou en bois)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;5 po&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;March&#233;-Noir.html#Tabati&#232;re&quot; title=&quot;March&#233; noir&quot;&gt;↓&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Tabati&#232;re-(Objet).html&quot; title=&quot;Tabati&#232;re&quot;&gt;Tabati&#232;re (en ivoire ou en m&#233;tal pr&#233;cieux)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;300 po&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;March&#233;-Noir.html#Tabati&#232;re&quot; title=&quot;March&#233; noir&quot;&gt;↓&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Tabati&#232;re-(Objet).html&quot; title=&quot;Tabati&#232;re&quot;&gt;Tabati&#232;re (en os ou en &#233;caille de tortue)&lt;/a&gt;&lt;/td&gt;&lt;td&gt;25 po&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;March&#233;-Noir.html#Th&#233; nocturne&quot; title=&quot;March&#233; noir&quot;&gt;↓&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Th&#233;-Nocturne-(Objet).html&quot; title=&quot;Th&#233; nocturne&quot;&gt;Th&#233; nocturne&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1 pa&lt;/td&gt;&lt;td&gt;—&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
